INSERT INTO `story` (`position`, `date_label`, `title`, `body`, `photo_slug`) VALUES (10, 'Capítulo uno · El comienzo', 'Llegaste tú', 'No sé explicar exactamente en qué momento pasó, pero un día me di cuenta de que mis días tenían otro color. Empezaste siendo una sonrisa que buscaba sin darme cuenta y terminaste siendo la persona en la que pienso al despertar.', 'juntos-al-anochecer');
INSERT INTO `story` (`position`, `date_label`, `title`, `body`, `photo_slug`) VALUES (20, 'Capítulo dos · Bajo el mismo cielo', 'Nuestras tardes azules', 'Hay cielos que se olvidan y cielos que se quedan para siempre. Los nuestros, con las nubes oscuras y ese último pedazo de sol, son de los que se quedan. Contigo, cualquier atardecer se vuelve un recuerdo.', 'beso-bajo-el-cielo');
INSERT INTO `story` (`position`, `date_label`, `title`, `body`, `photo_slug`) VALUES (30, 'Capítulo tres · Tu risa', 'La risa que me desarma', 'Me encanta que no tengas miedo de ser tú: la que hace caras, la que se ríe con todo el cuerpo, la que convierte una foto seria en una carcajada. Esa versión tuya es mi favorita.', 'risas-y-brackets');
INSERT INTO `story` (`position`, `date_label`, `title`, `body`, `photo_slug`) VALUES (40, 'Capítulo cuatro · Tú', 'Todo lo que eres', 'Eres fuerza y ternura al mismo tiempo. Eres la mirada que lo dice todo sin hablar, la que cuida, la que sueña en grande. Verte crecer y convertirte en la mujer que eres es uno de los regalos más bonitos de mi vida.', 'seydi-mirada');
INSERT INTO `story` (`position`, `date_label`, `title`, `body`, `photo_slug`) VALUES (50, 'Hoy · 18 años', 'Y lo que viene', 'Hoy empieza una etapa nueva para ti, y quiero estar ahí para verla. Que estos 18 sean el inicio de todo lo que sueñas: yo voy a estar a tu lado, aplaudiendo cada paso.', 'seydi-espejo');
INSERT INTO `gallery` (`position`, `photo_slug`, `caption`) VALUES (10, 'seydi-beso', 'Ese beso a la cámara que en realidad era para mí.');
INSERT INTO `gallery` (`position`, `photo_slug`, `caption`) VALUES (20, 'juntos-al-anochecer', 'Tú, yo y un cielo que parecía pintado.');
INSERT INTO `gallery` (`position`, `photo_slug`, `caption`) VALUES (30, 'seydi-mirada', 'Esa mirada que me dice todo sin decir nada.');
INSERT INTO `gallery` (`position`, `photo_slug`, `caption`) VALUES (40, 'beso-bajo-el-cielo', 'Mi lugar favorito: a tu lado.');
INSERT INTO `gallery` (`position`, `photo_slug`, `caption`) VALUES (50, 'seydi-espejo', 'Siempre con estilo propio.');
INSERT INTO `gallery` (`position`, `photo_slug`, `caption`) VALUES (60, 'risas-y-brackets', 'La risa más bonita del mundo, con brackets y todo.');
INSERT INTO `gallery` (`position`, `photo_slug`, `caption`) VALUES (70, 'seydi-traviesa', 'Tu lado travieso, mi favorito.');
INSERT INTO `moments` (`position`, `layout`, `date_label`, `title`, `body`, `author`, `place`, `photo_slug`) VALUES (10, 'polaroid', 'Un instante cualquiera', 'Tu lado travieso', 'Puedes estar seria un segundo y al siguiente estar sacándome la lengua. Así eres, y así te quiero.', '', '', 'seydi-traviesa');
INSERT INTO `moments` (`position`, `layout`, `date_label`, `title`, `body`, `author`, `place`, `photo_slug`) VALUES (20, 'quote', '', '', 'Contigo aprendí que los mejores momentos no se planean: simplemente pasan cuando estamos juntos.', 'Alejandro', '', NULL);
INSERT INTO `moments` (`position`, `layout`, `date_label`, `title`, `body`, `author`, `place`, `photo_slug`) VALUES (30, 'split', 'Al caer la tarde', 'Nuestro cielo', 'Ese cielo azul oscuro, la hierba, tu cabeza en mi hombro y la sensación de que el mundo podía esperar. Si pudiera repetir un día, sería uno así contigo.', '', '', 'juntos-al-anochecer');
INSERT INTO `moments` (`position`, `layout`, `date_label`, `title`, `body`, `author`, `place`, `photo_slug`) VALUES (40, 'flip', '', 'Toca para descubrir', 'Te debo una cita especial para celebrar tus 18. Tú eliges el lugar; yo pongo el resto.', '', '', 'seydi-espejo');
INSERT INTO `moments` (`position`, `layout`, `date_label`, `title`, `body`, `author`, `place`, `photo_slug`) VALUES (50, 'ticket', '12 de noviembre de 2026', 'Tus 18 años', 'Entrada válida para celebrar contigo hoy y todos los cumpleaños que vengan.', '', 'Donde tú estés', NULL);
